SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='51b0eaff-9164-508e-9cd9-c8fc679af06a'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('db0bac4a-7d04-5ecc-8c93-12983d127e0c','a35c0dd6-dbb7-57d1-af2c-a151f3f6b6ea')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='51b0eaff-9164-508e-9cd9-c8fc679af06a'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='51b0eaff-9164-508e-9cd9-c8fc679af06a'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('db0bac4a-7d04-5ecc-8c93-12983d127e0c','a35c0dd6-dbb7-57d1-af2c-a151f3f6b6ea')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='51b0eaff-9164-508e-9cd9-c8fc679af06a'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='db0bac4a-7d04-5ecc-8c93-12983d127e0c' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-worker-source-customer' AND q.fingerprint='f34efd94602f54843149268de669019090fcd31cde1deae687b4e76216458c24'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"worker-source-customer","status":"ok","value":{"customerProfileId":"51b0eaff-9164-508e-9cd9-c8fc679af06a","userId":"1a00123e-aadd-5e3b-aa9b-797fda5b72cc","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"db0bac4a-7d04-5ecc-8c93-12983d127e0c","semanticKey":"customer-controls-worker-source-customer","fingerprint":"f34efd94602f54843149268de669019090fcd31cde1deae687b4e76216458c24","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='8cd29b38-82f4-594b-834f-26551c544290' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='d7f56d78-4bfd-53b9-91fd-690d8dfb664f' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"51b0eaff-9164-508e-9cd9-c8fc679af06a"},"prior":null,"committed":{"id":"51b0eaff-9164-508e-9cd9-c8fc679af06a","userId":"1a00123e-aadd-5e3b-aa9b-797fda5b72cc","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='51b0eaff-9164-508e-9cd9-c8fc679af06a' AND c.user_id='1a00123e-aadd-5e3b-aa9b-797fda5b72cc' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='worker-source-customer' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='e66c79cb-9bdb-5cf3-84e6-0024060a604e' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"51b0eaff-9164-508e-9cd9-c8fc679af06a","userId":"1a00123e-aadd-5e3b-aa9b-797fda5b72cc","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='9c3b8f32-d0bb-5efa-aef9-0bf64edc8d81' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"1a00123e-aadd-5e3b-aa9b-797fda5b72cc","track":"customer","customerProfileId":"51b0eaff-9164-508e-9cd9-c8fc679af06a","sourceCreationRevision":"0","sourceCreationReceipt":"db0bac4a-7d04-5ecc-8c93-12983d127e0c","semanticKey":"customer_buyer_profile/51b0eaff-9164-508e-9cd9-c8fc679af06a/default-free-enrollment/v1"}'::jsonb)))=2));
